CREATE TABLE _cf_KV (
        key TEXT PRIMARY KEY,
        value BLOB
      ) WITHOUT ROWID;
CREATE TABLE access_reviews (id TEXT PRIMARY KEY, subject_user_id TEXT NOT NULL REFERENCES users(id), reviewer_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN ('retain','revoke','flag')), notes TEXT NOT NULL DEFAULT '', reviewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE account_deletions (user_id TEXT PRIMARY KEY REFERENCES users(id), deleted_by TEXT NOT NULL REFERENCES users(id), deleted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE account_password_resets (user_id TEXT PRIMARY KEY REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, consumed_at TEXT, requested_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_sessions(id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE automation_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), rule_id TEXT REFERENCES workflow_rules(id), subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, outcome TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_audit(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_entries(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),kind TEXT NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_profiles(customer_id TEXT PRIMARY KEY REFERENCES customers(id),data TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE commercial_events(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES commercial_records(id),actor_id TEXT NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,detail TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE commercial_records(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),kind TEXT NOT NULL CHECK(kind IN ('rfp','quotation','poc','prospection','opportunity','contract','project')),title TEXT NOT NULL,reference TEXT,stage TEXT NOT NULL DEFAULT 'new' CHECK(stage IN ('new','qualifying','preparing','submitted','negotiation','won','lost','on_hold','in_progress','completed')),value_amount REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'MUR',probability INTEGER NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),due_date TEXT,owner_id TEXT REFERENCES users(id),notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contract_audit (
 id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES managed_contracts(id),
 actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL,
 snapshot TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE contract_entries (
 id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES managed_contracts(id),
 kind TEXT NOT NULL CHECK(kind IN ('coverage','sla','renewal','obligation','document')),
 data TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE countries (code TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE country_leads(country_code TEXT NOT NULL REFERENCES countries(code), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(country_code,user_id));

CREATE TABLE customer_activities(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),activity_type TEXT NOT NULL CHECK(activity_type IN ('project','support','contract','quotation','opportunity')),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reference TEXT,owner_id TEXT REFERENCES users(id),due_date TEXT,notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_contacts(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),name TEXT NOT NULL,email TEXT,phone TEXT,job_title TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_profiles(customer_id TEXT PRIMARY KEY REFERENCES customers(id),industry TEXT,website TEXT,phone TEXT,address TEXT,status TEXT DEFAULT 'active',notes TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_user_access(user_id TEXT NOT NULL REFERENCES users(id),customer_id TEXT NOT NULL REFERENCES customers(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,customer_id));
CREATE TABLE customers (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, country_code TEXT REFERENCES countries(code), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_department_assignment_audit (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),previous_department_id TEXT,new_department_id TEXT,actor_id TEXT NOT NULL REFERENCES users(id),changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_department_memberships (user_id TEXT PRIMARY KEY REFERENCES users(id),department_id TEXT NOT NULL REFERENCES enterprise_departments(id),assigned_by TEXT NOT NULL REFERENCES users(id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_departments (id TEXT PRIMARY KEY,name TEXT NOT NULL,country_code TEXT NOT NULL CHECK(country_code IN ('MU','MG','RW','BI')),manager_id TEXT REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(name,country_code));
CREATE TABLE enterprise_management_audit(id TEXT PRIMARY KEY,department_id TEXT NOT NULL,actor_id TEXT NOT NULL,old_manager_id TEXT,new_manager_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_routing_rules (id TEXT PRIMARY KEY,department_id TEXT NOT NULL REFERENCES enterprise_departments(id),section TEXT NOT NULL CHECK(section IN ('technical','financial')),workflow_type TEXT NOT NULL,default_owner_id TEXT NOT NULL REFERENCES users(id),enabled INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL REFERENCES users(id),UNIQUE(department_id,section,workflow_type));
CREATE TABLE enterprise_settings (setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_settings_audit (id TEXT PRIMARY KEY,setting_key TEXT NOT NULL,old_value TEXT,new_value TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_team_memberships (user_id TEXT PRIMARY KEY REFERENCES users(id),team_id TEXT NOT NULL REFERENCES enterprise_teams(id),assigned_by TEXT NOT NULL REFERENCES users(id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enterprise_teams (id TEXT PRIMARY KEY,department_id TEXT NOT NULL REFERENCES enterprise_departments(id),name TEXT NOT NULL,lead_user_id TEXT REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(department_id,name));
CREATE TABLE enterprise_workflow_options (id TEXT PRIMARY KEY,section TEXT NOT NULL CHECK(section IN ('technical','financial')),kind TEXT NOT NULL CHECK(kind IN ('type','status')),code TEXT NOT NULL,label TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 100,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),updated_by TEXT NOT NULL REFERENCES users(id),UNIQUE(section,kind,code));

CREATE TABLE federated_identities (provider TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(provider,issuer,subject), UNIQUE(provider,user_id));
CREATE TABLE identity_audit(id TEXT PRIMARY KEY, actor_id TEXT, event_type TEXT NOT NULL, target_id TEXT, country_code TEXT, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE identity_invitations (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,requested_role TEXT NOT NULL,country_scope TEXT NOT NULL,invitation_status TEXT NOT NULL DEFAULT 'awaiting_activation',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,activated_at TEXT);
CREATE TABLE identity_provider_settings (id TEXT PRIMARY KEY CHECK(id='default'), mode TEXT NOT NULL DEFAULT 'internal' CHECK(mode IN ('internal','hybrid')), tenant_id TEXT, client_id TEXT, issuer TEXT, updated_by TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_limits (id TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, blocked_until TEXT);
CREATE TABLE managed_contracts (
 id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id),
 reference TEXT NOT NULL COLLATE NOCASE UNIQUE, title TEXT NOT NULL,
 contract_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft',
 start_date TEXT NOT NULL, end_date TEXT NOT NULL, currency TEXT NOT NULL,
 amount TEXT NOT NULL DEFAULT '', data TEXT NOT NULL DEFAULT '{}',
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notification_outbox(id TEXT PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES workflow_alerts(id),recipient_id TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL DEFAULT 'email',status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TEXT,UNIQUE(alert_id,recipient_id,channel));
CREATE TABLE oidc_login_states (state_hash TEXT PRIMARY KEY, nonce_hash TEXT NOT NULL, code_verifier TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, linking_user_id TEXT);
CREATE TABLE opportunities (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'prospection', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE regional_activities (id TEXT PRIMARY KEY,title TEXT NOT NULL,activity_type TEXT NOT NULL CHECK(activity_type IN ('project','task','poc','rfp','prospection','quotation','workshop','incident','other')),status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','planned','in_progress','waiting','completed','cancelled')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','critical')),country_code TEXT NOT NULL CHECK(country_code IN ('MU','MG','RW','BI')),customer_id TEXT,owner_id TEXT REFERENCES users(id),description TEXT NOT NULL DEFAULT '',due_date TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, section TEXT NOT NULL DEFAULT 'technical' CHECK(section IN ('technical','financial')), workflow_type TEXT, workflow_status TEXT);
CREATE TABLE regional_activity_financials (activity_id TEXT PRIMARY KEY REFERENCES regional_activities(id),reference TEXT NOT NULL DEFAULT '',amount REAL NOT NULL DEFAULT 0 CHECK(amount>=0),currency TEXT NOT NULL DEFAULT 'MUR',probability INTEGER NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),expected_close TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE regional_activity_updates (id TEXT PRIMARY KEY,activity_id TEXT NOT NULL REFERENCES regional_activities(id),author_id TEXT NOT NULL REFERENCES users(id),note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE regional_forecast_audit (id TEXT PRIMARY KEY,target_id TEXT NOT NULL REFERENCES regional_forecast_targets(id),actor_id TEXT NOT NULL REFERENCES users(id),previous_amount REAL,new_amount REAL NOT NULL,changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE regional_forecast_targets (id TEXT PRIMARY KEY,financial_year TEXT NOT NULL,country_code TEXT NOT NULL CHECK(country_code IN ('MU','MG','RW','BI')),currency TEXT NOT NULL DEFAULT 'MUR',target_amount REAL NOT NULL CHECK(target_amount>=0),created_by TEXT NOT NULL REFERENCES users(id),updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(financial_year,country_code,currency));
CREATE TABLE registration_activation_tokens (request_id TEXT PRIMARY KEY REFERENCES registration_requests(id), user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE registration_requests(id TEXT PRIMARY KEY, email TEXT NOT NULL, display_name TEXT NOT NULL, country_code TEXT NOT NULL REFERENCES countries(code), organization_name TEXT, status TEXT NOT NULL DEFAULT 'pending_verification' CHECK(status IN ('pending_verification','pending_approval','approved','rejected')), verification_hash TEXT, verification_expires_at TEXT, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE renewals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, expiry_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE service_tickets(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','critical')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','on_hold','resolved','closed')),assigned_to TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,first_response_at TEXT,resolved_at TEXT,response_due_at TEXT,resolution_due_at TEXT);
CREATE TABLE sla_policies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), priority TEXT NOT NULL, response_minutes INTEGER NOT NULL, resolution_minutes INTEGER NOT NULL);
CREATE TABLE sso_link_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), issuer TEXT NOT NULL, subject TEXT NOT NULL, requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by TEXT, reviewed_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), UNIQUE(issuer,subject));
CREATE TABLE support_group_members (group_id TEXT NOT NULL REFERENCES support_groups(id), user_id TEXT NOT NULL REFERENCES users(id), group_role TEXT NOT NULL CHECK(group_role IN ('member','lead')), PRIMARY KEY(group_id,user_id));
CREATE TABLE support_groups (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(organization_id,name));
CREATE TABLE task_events(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES work_tasks(id),actor_id TEXT NOT NULL REFERENCES users(id),event TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ticket_assignments (ticket_id TEXT PRIMARY KEY REFERENCES tickets(id), group_id TEXT NOT NULL REFERENCES support_groups(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ticket_events (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), actor_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), number INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('incident','request','problem','change')), priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')), status TEXT NOT NULL CHECK(status IN ('new','assigned','in_progress','pending','resolved','closed')), requester_id TEXT NOT NULL REFERENCES users(id), assignee_id TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT, UNIQUE(organization_id,number));
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('super_admin','admin','country_lead','regional_manager','group_leader','technician','requester')), PRIMARY KEY(user_id,role));
CREATE TABLE users (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','agent','requester')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, country_code TEXT REFERENCES countries(code), account_status TEXT NOT NULL DEFAULT 'inactive' CHECK(account_status IN ('active','inactive','locked')), password_salt TEXT, password_hash TEXT, password_iterations INTEGER, password_changed_at TEXT);

CREATE TABLE work_tasks(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),activity_id TEXT REFERENCES customer_activities(id),title TEXT NOT NULL,description TEXT,assignee_id TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id),priority TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'todo',due_date TEXT,completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workflow_alerts(id TEXT PRIMARY KEY,rule TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,country_code TEXT NOT NULL,message TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,acknowledged_by TEXT REFERENCES users(id),acknowledged_at TEXT,UNIQUE(rule,entity_type,entity_id));
CREATE TABLE workflow_rules (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, event_name TEXT NOT NULL, conditions_json TEXT NOT NULL, actions_json TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY,rule TEXT NOT NULL,entity_id TEXT NOT NULL,executed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(rule,entity_id,executed_at));
